public abstract class AbstractCommand implements Command {
  protected final String name;
  protected final String commandCode;
  protected String helpText;
  protected CommandParser parser;

  protected AbstractCommand(String name, String commandCode) {
    if (name != null) {
      helpText = name + Color.WHITE + " : " + t(commandCode);

      int splitIndex = name.indexOf(" ");
      if (splitIndex != -1) {
        name = name.substring(0, splitIndex);
      }
    } else {
      helpText = t(commandCode);
    }

    this.name = name;
    this.commandCode = commandCode;
  }

  public String getName() {
    return name;
  }

  public String getHelpText(String prefix) {
    if (name != null) {
      return Color.DARK_GREEN + prefix + helpText;
    } else {
      return helpText;
    }
  }

  public boolean shouldPassThroughToConsole(Server server) {
    return (server.permissions.commandShouldPassThroughToMod(getName())
        || server.options.getBoolean("forwardAllCommands"))
        && server.options.contains("alternateJarFile");
  }

